SET NAMES utf8mb4;
START TRANSACTION;
INSERT IGNORE INTO sandboxes (`id`,`name`,`payload`) VALUES ('local','Local execution (trusted tasks only)','{"id":"local","name":"Local execution (trusted tasks only)","driver":"local"}') AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(sandboxes.id = incoming.id AND BINARY sandboxes.name = BINARY '本地执行（仅可信任务）'
    AND SHA2(CAST(sandboxes.payload AS CHAR CHARACTER SET utf8mb4),256) = '4807cae3726cc315a0374504a5c45f2d50189b42ccb565b7c0bff3c5a58fa43c',
    incoming.payload, sandboxes.payload),
  name = IF(sandboxes.id = incoming.id AND BINARY sandboxes.name = BINARY '本地执行（仅可信任务）'
    AND sandboxes.payload = incoming.payload, incoming.name, sandboxes.name);
INSERT IGNORE INTO sandboxes (`id`,`name`,`payload`) VALUES ('generic-docker','Docker sandbox','{"id":"generic-docker","name":"Docker sandbox","shared":true,"driver":"docker","dockerfileId":"generic-backend","readOnlyRootFS":false}') AS incoming
