    incoming.payload, sandboxes.payload),
  name = IF(sandboxes.id = incoming.id AND BINARY sandboxes.name = BINARY 'Docker 隔离沙箱'
    AND sandboxes.payload = incoming.payload, incoming.name, sandboxes.name);
INSERT IGNORE INTO dockerfiles (`id`,`name`,`payload`) VALUES ('generic-backend','Shared development environment','{"id":"generic-backend","name":"Shared development environment","shared":true,"content":"FROM node:22-bookworm\\nRUN apt-get update && apt-get install -y --no-install-recommends git openssh-client python3 ripgrep ca-certificates curl && rm -rf /var/lib/apt/lists/*\\nRUN npm install -g @openai/codex @anthropic-ai/claude-code @tencent-ai/codebuddy-code\\nWORKDIR /workspace\\n"}') AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(dockerfiles.id = incoming.id AND BINARY dockerfiles.name = BINARY '公共开发环境'
    AND SHA2(CAST(dockerfiles.payload AS CHAR CHARACTER SET utf8mb4),256) = '2bc98be343adcf7e889beb805ef25b9bf1ac8db101d08734cb2cd8f4eb5be8fa',
    incoming.payload, dockerfiles.payload),
  name = IF(dockerfiles.id = incoming.id AND BINARY dockerfiles.name = BINARY '公共开发环境'
    AND dockerfiles.payload = incoming.payload, incoming.name, dockerfiles.name);
INSERT IGNORE INTO rules (`id`,`name`,`payload`) VALUES ('public-engineering','Engineering and verification rules','{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"public-engineering","name":"Engineering and verification rules","shared":true,"priority":100,"content":"Read the repository instructions and confirm the scope first. Change only the files the task requires. Keep credentials private and report genuine test and delivery evidence. Use the project’s own build and test commands and report the results and limitations. Review the diff before opening a PR. Merging the default branch requires explicit task authorization."}') AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(rules.id = incoming.id AND BINARY rules.name = BINARY '工程与验证约束'
    AND SHA2(CAST(rules.payload AS CHAR CHARACTER SET utf8mb4),256) = '1e4ad7e31346cbbe281e4db9c8316bd7da49a149420def6ef7b779830a852cab',
    incoming.payload, rules.payload),
  name = IF(rules.id = incoming.id AND BINARY rules.name = BINARY '工程与验证约束'
    AND rules.payload = incoming.payload, incoming.name, rules.name);
INSERT IGNORE INTO generic_templates (id,name,payload,updated_at) VALUES ('generic-backend-delivery','Backend delivery SOP','{"Workflow":{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-backend-delivery","name":"Backend delivery SOP","revision":1,"status":"published","description":"Deliver a backend requirement from clarification through independent review.","sandboxProfileId":"generic-docker","generic":true,"owner":"LoopForge","tags":["public"],"nodes":[{"id":"clarify","name":"Clarify requirements","type":"agent","agentId":"generic-backend-delivery-clarify","maxAttempts":2,"position":{"x":100,"y":150},"artifactOutputs":[{"name":"clarify","path":"requirement.md","mediaType":"text/markdown","required":true}]},{"id":"design","name":"Design the solution","type":"agent","agentId":"generic-backend-delivery-design","maxAttempts":2,"position":{"x":345,"y":150},"artifactOutputs":[{"name":"design","path":"design.md","mediaType":"text/markdown","required":true}]},{"id":"implement","name":"Implement changes","type":"agent","agentId":"generic-backend-delivery-implement","maxAttempts":2,"position":{"x":590,"y":150},"artifactOutputs":[{"name":"implement","path":"implementation.md","mediaType":"text/markdown","required":true}]},{"id":"review","name":"Independent review","type":"agent","agentId":"generic-backend-delivery-review","maxAttempts":2,"position":{"x":835,"y":150},"artifactOutputs":[{"name":"review","path":"review.md","mediaType":"text/markdown","required":true}]},{"id":"test","name":"Run tests","type":"agent","agentId":"generic-backend-delivery-test","maxAttempts":2,"position":{"x":1080,"y":150},"artifactOutputs":[{"name":"test","path":"test-report.md","mediaType":"text/markdown","required":true}]},{"id":"accept","name":"Human acceptance","type":"approval","maxAttempts":1,"rejectTo":"implement","position":{"x":1325,"y":150}},{"id":"deliver","name":"Delivery summary","type":"agent","agentId":"generic-backend-delivery-deliver","maxAttempts":2,"position":{"x":1815,"y":150},"artifactOutputs":[{"name":"deliver","path":"delivery.md","mediaType":"text/markdown","required":true}]},{"id":"mr","name":"Open a merge request","type":"agent","agentId":"generic-backend-delivery-mr","maxAttempts":2,"position":{"x":1570,"y":150},"artifactOutputs":[{"name":"mr-body","path":"mr-body.md","mediaType":"text/markdown","required":true}]}],"edges":[{"id":"e-0","source":"clarify","target":"design","when":"success"},{"id":"e-1","source":"design","target":"implement","when":"success"},{"id":"e-2","source":"implement","target":"review","when":"success"},{"id":"e-3","source":"review","target":"test","when":"success"},{"id":"e-4","source":"test","target":"accept","when":"success"},{"id":"e-5","source":"accept","target":"mr","when":"success"},{"id":"e-6","source":"mr","target":"deliver","when":"success"}]},"Agents":[{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-backend-delivery-clarify","name":"Clarify requirements","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Backend services, data and APIs. Confirm the goal, scope, users, boundaries and testable acceptance criteria. Write requirement.md before coding.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-backend-delivery-design","name":"Design the solution","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Backend services, data and APIs. Read the confirmed requirements and available code. Describe the smallest implementation, interface changes, risks and validation plan in design.md. A new project can be designed and built in the task workspace without a repository. Changes to existing systems and bug fixes require their source. If it is missing, report the blocker and request the code.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-backend-delivery-implement","name":"Implement changes","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Backend services, data and APIs. Implement the scope agreed in requirement.md and design.md. Run the applicable checks and record the implementation, changes and results in implementation.md.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-backend-delivery-review","name":"Independent review","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Backend services, data and APIs. Independently inspect the changes and test evidence. List defects by severity, location and impact, with proposed fixes in review.md. Explicitly write REJECT for a blocking defect. Never claim checks passed without evidence.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-backend-delivery-test","name":"Run tests","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Backend services, data and APIs. Run real project tests, builds and required end-to-end scenarios against the acceptance criteria. Fix problems and retest as needed. Record commands, exit codes, results and unverified scope in test-report.md.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-backend-delivery-deliver","name":"Delivery summary","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Backend services, data and APIs. Verify the actual artifacts and test evidence from each step. Write the completed work, test results, known limitations, and deliverables to delivery.md. For a task without a linked repository, deliver the source and reports in the workspace. No Git token is required. The merge-request step already committed and pushed the code and opened the MR/PR. Copy its URL, branches and commit SHA from mr-body.md into the delivery manifest. Do not change code, push, open another PR or merge at this step.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-11-16T00:00:00Z","id":"generic-backend-delivery-mr","name":"Open a merge request","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Backend services, data and APIs. Human acceptance is complete. Commit this task’s changes on its working branch, push it, and open an MR/PR. Do not change application logic at this step.\\n\\n1. Without a linked repository, leave the source in the task workspace. Record that fact and list the delivered files in mr-body.md. Submit pass without pushing or opening an MR/PR.\\n2. Process each linked checkout separately. Skip unchanged repositories. Verify the checkout is already on this task’s working branch. Never commit to the default branch, switch branches or create a new branch here. Inspect git status and the diff. Commit only the task’s source changes. Exclude .agentflow, dependencies, build products and SOP-stage documents. Summarize the changes in the commit message and push the working branch with git push -u origin. The platform provides credentials. Never print, echo or persist tokens.\\n3. Target the branch specified by the repository context. Use the host CLI (gh or glab), a configured MCP tool, or the official hosting API. If the API requires a token, use git credential fill for the repository host and keep the result in process memory. Update an existing MR/PR for the same source and target branches.\\n4. Summarize the change in the title. Include the requirement, changes, test results from test-report.md and known limitations in the description. Never merge, push the default branch or force-push.\\n5. Record each MR/PR URL, source and target branches, and commit SHA in mr-body.md.\\n6. If a push or MR/PR creation fails, record the reason in mr-body.md and submit human. In actionRequired, describe the intervention needed, such as configuring a Git token and retrying or creating the MR manually. Do not submit pass on failure.\\n\\nMR constraints: {{existingMR}}\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}","loop":{"enabled":true,"maxIterations":2,"exitCondition":"all_gates_pass","onExhausted":"human"},"verification":[{"id":"mr-pushed","name":"Changes committed and pushed","mode":"command","stage":"after_execution","commands":["fail=0\\ntab=\\"$(printf ''\\\\t'')\\"\\nwhile IFS=\\"$tab\\" read -r d work base; do\\n  [ -n \\"$d\\" ] || continue\\n  dirty=\\"$(git -C \\"$d\\" status --porcelain --untracked-files=all -- . \\":(exclude).agentflow\\" \\":(exclude,glob)**/node_modules/**\\")\\" || { printf \\"%s is not a usable Git checkout\\\\n\\" \\"$d\\"; fail=1; continue; }\\n  if [ -n \\"$dirty\\" ]; then printf \\"%s has uncommitted changes:\\\\n%s\\\\n\\" \\"$d\\" \\"$dirty\\"; fail=1; continue; fi\\n  refs=HEAD\\n  if git -C \\"$d\\" rev-parse -q --verify \\"refs/heads/$work\\" >/dev/null; then refs=\\"HEAD refs/heads/$work\\"; fi\\n  ahead=\\"$(git -C \\"$d\\" rev-list --count $refs --not \\"refs/remotes/origin/$base\\")\\" || { printf \\"%s cannot find target branch origin/%s\\\\n\\" \\"$d\\" \\"$base\\"; fail=1; continue; }\\n  [ \\"$ahead\\" != 0 ] || continue\\n  branch=\\"$(git -C \\"$d\\" branch --show-current)\\"\\n  if [ \\"$branch\\" != \\"$work\\" ]; then printf \\"%s is on %s, expected working branch %s\\\\n\\" \\"$d\\" \\"${branch:-detached HEAD}\\" \\"$work\\"; fail=1; continue; fi\\n  head=\\"$(git -C \\"$d\\" rev-parse HEAD)\\"\\n  pushed=\\"$(git -C \\"$d\\" ls-remote origin \\"refs/heads/$work\\")\\" || { printf \\"%s cannot read remote origin\\\\n\\" \\"$d\\"; fail=1; continue; }\\n  if [ \\"${pushed%%\\"$tab\\"*}\\" != \\"$head\\" ]; then printf \\"%s working branch %s on origin is not at %s; the changes have not been pushed\\\\n\\" \\"$d\\" \\"$work\\" \\"$head\\"; fail=1; fi\\ndone <<EOF\\n$AGENTFLOW_WORK_BRANCHES\\nEOF\\nexit \\"$fail\\""],"required":true,"onFailure":"loop","executionScope":"run"},{"id":"mr-opened","name":"Merge request created","mode":"mr","stage":"after_execution","required":true,"onFailure":"loop"}]}],"Rules":[{"id":"public-engineering","name":"Engineering and verification rules","shared":true,"priority":100,"content":"Read the repository instructions and confirm the scope first. Change only the files the task requires. Keep credentials private and report genuine test and delivery evidence. Use the project’s own build and test commands and report the results and limitations. Review the diff before opening a PR. Merging the default branch requires explicit task authorization. Repository linking is optional. Deliver source and reports from the task workspace for a new project. For existing code changes or bug fixes, obtain the source or report the blocker and request it. Pushing and opening PRs require a target repository and credentials."}],"Skills":[]}',UTC_TIMESTAMP()) AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(generic_templates.id = incoming.id AND BINARY generic_templates.name = BINARY '通用后端交付 SOP'
    AND SHA2(CAST(generic_templates.payload AS CHAR CHARACTER SET utf8mb4),256) = 'ec38e2767799306a8b9e8086f9287032be0c11134fc4676b151a2c994dbaa666',
    incoming.payload, generic_templates.payload),
  name = IF(generic_templates.id = incoming.id AND BINARY generic_templates.name = BINARY '通用后端交付 SOP'
    AND generic_templates.payload = incoming.payload, incoming.name, generic_templates.name);
INSERT IGNORE INTO generic_templates (id,name,payload,updated_at) VALUES ('generic-frontend-delivery','Frontend delivery SOP','{"Workflow":{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-frontend-delivery","name":"Frontend delivery SOP","revision":1,"status":"published","description":"Deliver a frontend change from page design through interaction and regression testing.","sandboxProfileId":"generic-docker","generic":true,"owner":"LoopForge","tags":["public"],"nodes":[{"id":"clarify","name":"Clarify requirements","type":"agent","agentId":"generic-frontend-delivery-clarify","maxAttempts":2,"position":{"x":100,"y":150},"artifactOutputs":[{"name":"clarify","path":"requirement.md","mediaType":"text/markdown","required":true}]},{"id":"design","name":"Design the solution","type":"agent","agentId":"generic-frontend-delivery-design","maxAttempts":2,"position":{"x":345,"y":150},"artifactOutputs":[{"name":"design","path":"design.md","mediaType":"text/markdown","required":true}]},{"id":"implement","name":"Implement changes","type":"agent","agentId":"generic-frontend-delivery-implement","maxAttempts":2,"position":{"x":590,"y":150},"artifactOutputs":[{"name":"implement","path":"implementation.md","mediaType":"text/markdown","required":true}]},{"id":"review","name":"Independent review","type":"agent","agentId":"generic-frontend-delivery-review","maxAttempts":2,"position":{"x":835,"y":150},"artifactOutputs":[{"name":"review","path":"review.md","mediaType":"text/markdown","required":true}]},{"id":"test","name":"Run tests","type":"agent","agentId":"generic-frontend-delivery-test","maxAttempts":2,"position":{"x":1080,"y":150},"artifactOutputs":[{"name":"test","path":"test-report.md","mediaType":"text/markdown","required":true}]},{"id":"accept","name":"Human acceptance","type":"approval","maxAttempts":1,"rejectTo":"implement","position":{"x":1325,"y":150}},{"id":"deliver","name":"Delivery summary","type":"agent","agentId":"generic-frontend-delivery-deliver","maxAttempts":