ork\\"; fi\\n  ahead=\\"$(git -C \\"$d\\" rev-list --count $refs --not \\"refs/remotes/origin/$base\\")\\" || { printf \\"%s cannot find target branch origin/%s\\\\n\\" \\"$d\\" \\"$base\\"; fail=1; continue; }\\n  [ \\"$ahead\\" != 0 ] || continue\\n  branch=\\"$(git -C \\"$d\\" branch --show-current)\\"\\n  if [ \\"$branch\\" != \\"$work\\" ]; then printf \\"%s is on %s, expected working branch %s\\\\n\\" \\"$d\\" \\"${branch:-detached HEAD}\\" \\"$work\\"; fail=1; continue; fi\\n  head=\\"$(git -C \\"$d\\" rev-parse HEAD)\\"\\n  pushed=\\"$(git -C \\"$d\\" ls-remote origin \\"refs/heads/$work\\")\\" || { printf \\"%s cannot read remote origin\\\\n\\" \\"$d\\"; fail=1; continue; }\\n  if [ \\"${pushed%%\\"$tab\\"*}\\" != \\"$head\\" ]; then printf \\"%s working branch %s on origin is not at %s; the changes have not been pushed\\\\n\\" \\"$d\\" \\"$work\\" \\"$head\\"; fail=1; fi\\ndone <<EOF\\n$AGENTFLOW_WORK_BRANCHES\\nEOF\\nexit \\"$fail\\""],"required":true,"onFailure":"loop","executionScope":"run"},{"id":"mr-opened","name":"Merge request created","mode":"mr","stage":"after_execution","required":true,"onFailure":"loop"}]}],"Rules":[{"id":"public-engineering","name":"Engineering and verification rules","shared":true,"priority":100,"content":"Read the repository instructions and confirm the scope first. Change only the files the task requires. Keep credentials private and report genuine test and delivery evidence. Use the project’s own build and test commands and report the results and limitations. Review the diff before opening a PR. Merging the default branch requires explicit task authorization. Repository linking is optional. Deliver source and reports from the task workspace for a new project. For existing code changes or bug fixes, obtain the source or report the blocker and request it. Pushing and opening PRs require a target repository and credentials."}],"Skills":[]}',UTC_TIMESTAMP()) AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(generic_templates.id = incoming.id AND BINARY generic_templates.name = BINARY '通用前端交付 SOP'
    AND SHA2(CAST(generic_templates.payload AS CHAR CHARACTER SET utf8mb4),256) = '19b3230cc4d2c04e2e3a5f061d1f48696a0de32f4980dde4559183943744c9c7',
    incoming.payload, generic_templates.payload),
  name = IF(generic_templates.id = incoming.id AND BINARY generic_templates.name = BINARY '通用前端交付 SOP'
    AND generic_templates.payload = incoming.payload, incoming.name, generic_templates.name);
INSERT IGNORE INTO generic_templates (id,name,payload,updated_at) VALUES ('issue-fix-production','Bug-fix SOP','{"Workflow":{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"issue-fix-production","name":"Bug-fix SOP","revision":1,"status":"published","description":"Reproduce the issue, fix it, review independently and run regression tests.","sandboxProfileId":"generic-docker","generic":true,"owner":"LoopForge","tags":["public"],"nodes":[{"id":"clarify","name":"Clarify requirements","type":"agent","agentId":"issue-fix-production-clarify","maxAttempts":2,"position":{"x":100,"y":150},"artifactOutputs":[{"name":"clarify","path":"requirement.md","mediaType":"text/markdown","required":true}]},{"id":"design","name":"Design the solution","type":"agent","agentId":"issue-fix-production-design","maxAttempts":2,"position":{"x":345,"y":150},"artifactOutputs":[{"name":"design","path":"design.md","mediaType":"text/markdown","required":true}]},{"id":"implement","name":"Implement changes","type":"agent","agentId":"issue-fix-production-implement","maxAttempts":2,"position":{"x":590,"y":150},"artifactOutputs":[{"name":"implement","path":"implementation.md","mediaType":"text/markdown","required":true}]},{"id":"review","name":"Independent review","type":"agent","agentId":"issue-fix-production-review","maxAttempts":2,"position":{"x":835,"y":150},"artifactOutputs":[{"name":"review","path":"review.md","mediaType":"text/markdown","required":true}]},{"id":"test","name":"Run tests","type":"agent","agentId":"issue-fix-production-test","maxAttempts":2,"position":{"x":1080,"y":150},"artifactOutputs":[{"name":"test","path":"test-report.md","mediaType":"text/markdown","required":true}]},{"id":"accept","name":"Human acceptance","type":"approval","maxAttempts":1,"rejectTo":"implement","position":{"x":1325,"y":150}},{"id":"deliver","name":"Delivery summary","type":"agent","agentId":"issue-fix-production-deliver","maxAttempts":2,"position":{"x":1815,"y":150},"artifactOutputs":[{"name":"deliver","path":"delivery.md","mediaType":"text/markdown","required":true}]},{"id":"mr","name":"Open a merge request","type":"agent","agentId":"issue-fix-production-mr","maxAttempts":2,"position":{"x":1570,"y":150},"artifactOutputs":[{"name":"mr-body","path":"mr-body.md","mediaType":"text/markdown","required":true}]}],"edges":[{"id":"e-0","source":"clarify","target":"design","when":"success"},{"id":"e-1","source":"design","target":"implement","when":"success"},{"id":"e-2","source":"implement","target":"review","when":"success"},{"id":"e-3","source":"review","target":"test","when":"success"},{"id":"e-4","source":"test","target":"accept","when":"success"},{"id":"e-5","source":"accept","target":"mr","when":"success"},{"id":"e-6","source":"mr","target":"deliver","when":"success"}]},"Agents":[{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"issue-fix-production-clarify","name":"Clarify requirements","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Bug reproduction, diagnosis and regression testing. Confirm the goal, scope, users, boundaries and testable acceptance criteria. Write requirement.md before coding. A linked repository is optional, but you need the affected code and reproduction materials. Request any missing inputs. Never invent a reproduction or claim a fix without evidence.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"issue-fix-production-design","name":"Design the solution","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Bug reproduction, diagnosis and regression testing. Read the confirmed requirements and available code. Describe the smallest implementation, interface changes, risks and validation plan in design.md. A new project can be designed and built in the task workspace without a repository. Changes to existing systems and bug fixes require their source. If it is missing, report the blocker and request the code.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"issue-fix-production-implement","name":"Implement changes","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Bug reproduction, diagnosis and regression testing. Implement the scope agreed in requirement.md and design.md. Run the applicable checks and record the implementation, changes and results in implementation.md.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"issue-fix-production-review","name":"Independent review","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Bug reproduction, diagnosis and regression testing. Independently inspect the changes and test evidence. List defects by severity, location and impact, with proposed fixes in review.md. Explicitly write REJECT for a blocking defect. Never claim checks passed without evidence.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"issue-fix-production-test","name":"Run tests","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Bug reproduction, diagnosis and regression testing. Run real project tests, builds and required end-to-end scenarios against the acceptance criteria. Fix problems and retest as needed. Record commands, exit codes, results and unverified scope in test-report.md.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"issue-fix-production-deliver","name":"Delivery summary","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Bug reproduction, diagnosis and regression testing. Verify the actual artifacts and test evidence from each step. Write the completed work, test results, known limitations, and deliverables to delivery.md. For a task without a linked repository, deliver the source and reports in the workspace. No Git token is required. The merge-request step already committed and pushed the code and opened the MR/PR. Copy its URL, branches and commit SHA from mr-body.md into the delivery manifest. Do not change code, push, open another PR or merge at this step.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-11-16T00:00:00Z","id":"issue-fix-production-mr","name":"Open a merge request","executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Bug reproduction, diagnosis and regression testing. Human acceptance is complete. Commit this task’s changes on its working branch, push it, and open an MR/PR. Do not change application logic at this step.\\n\\n1. Without a linked repository, leave the source in the task workspace. Record that fact and list the delivered files in mr-body.md. Submit pass without pushing or opening an MR/PR.\\n2. Process each linked checkout separately. Skip unchanged repositories. Verify the checkout is already on this task’s working branch. Never commit to the default branch, switch branches or create a new branch here. Inspect git status and the diff. Commit only the task’s source changes. Exclude .agentflow, dependencies, build products and SOP-stage documents. Summarize the changes in the commit message and push the working branch with git push -u origin. The platform provides credentials. Never print, echo or persist tokens.\\n3. Target the branch specified by the repository context. Use the host CLI (gh or glab), a configured MCP tool, or the official hosting API. If the API requires a token, use git credential fill for the repository host and keep the result in process memory. Update an existing MR/PR for the same source and target branches.\\n4. Summarize the change in the title. Include the requirement, changes, test results from test-report.md and known limitations in the description. Never merge, push the default branch or force-push.\\n5. Record each MR/PR URL, source and target branches, and commit SHA in mr-body.md.\\n6. If a push or MR/PR creation fails, record the reason in mr-body.md and submit human. In actionRequired, describe the intervention needed, such as configuring a Git token and retrying or creating the MR manually. Do not submit pass on failure.\\n\\nMR constraints: {{existingMR}}\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}","loop":{"enabled":true,"maxIterations":2,"exitCondition":"all_gates_pass","onExhausted":"human"},"verification":[{"id":"mr-pushed","name":"Changes committed and pushed","mode":"command","stage":"after_execution","commands":["fail=0\\ntab=\\"$(printf ''\\\\t'')\\"\\nwhile IFS=\\"$tab\\" read -r d work base; do\\n  [ -n \\"$d\\" ] || continue\\n  dirty=\\"$(git -C \\"$d\\" status --porcelain --untracked-files=all -- . \\":(exclude).agentflow\\" \\":(exclude,glob)**/node_modules/**\\")\\" || { printf \\"%s is not a usable Git checkout\\\\n\\" \\"$d\\"; fail=1; continue; }\\n  if [ -n \\"$dirty\\" ]; then printf \\"%s has uncommitted changes:\\\\n%s\\\\n\\" \\"$d\\" \\"$dirty\\"; fail=1; continue; fi\\n  refs=HEAD\\n  if git -C \\"$d\\" rev-parse -q --verify \\"refs/heads/$work\\" >/dev/null; then refs=\\"HEAD refs/heads/$work\\"; fi\\n  ahead=\\"$(git -C \\"$d\\" rev-list --count $refs --not \\"refs/remotes/origin/$base\\")\\" || { printf \\"%s cannot find target branch origin/%s\\\\n\\" \\"$d\\" \\"$base\\"; fail=1; continue; }\\n  [ \\"$ahead\\" != 0 ] || continue\\n  branch=\\"$(git -C \\"$d\\" branch --show-current)\\"\\n  if [ \\"$branch\\" != \\"$work\\" ]; then printf \\"%s is on %s, expected working branch %s\\\\n\\" \\"$d\\" \\"${branch:-detached HEAD}\\" \\"$work\\"; fail=1; continue; fi\\n  head=\\"$(git -C \\"$d\\" rev-parse HEAD)\\"\\n  pushed=\\"$(git -C \\"$d\\" ls-remote origin \\"refs/heads/$work\\")\\" || { printf \\"%s cannot read remote origin\\\\n\\" \\"$d\\"; fail=1; continue; }\\n  if [ \\"${pushed%%\\"$tab\\"*}\\" != \\"$head\\" ]; then printf \\"%s working branch %s on origin is not at %s; the changes have not been pushed\\\\n\\" \\"$d\\" \\"$work\\" \\"$head\\"; fail=1; fi\\ndone <<EOF\\n$AGENTFLOW_WORK_BRANCHES\\nEOF\\nexit \\"$fail\\""],"required":true,"onFailure":"loop","executionScope":"run"},{"id":"mr-opened","name":"Merge request created","mode":"mr","stage":"after_execution","required":true,"onFailure":"loop"}]}],"Rules":[{"id":"public-engineering","name":"Engineering and verification rules","shared":true,"priority":100,"content":"Read the repository instructions and confirm the scope first. Change only the files the task requires. Keep credentials private and report genuine test and delivery evidence. Use the project’s own build and test commands and report the results and limitations. Review the diff before opening a PR. Merging the default branch requires explicit task authorization. Repository linking is optional. Deliver source and reports from the task workspace for a new project. For existing code changes or bug fixes, obtain the source or report the blocker and request it. Pushing and opening PRs require a target repository and credentials."}],"Skills":[]}',UTC_TIMESTAMP()) AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(generic_templates.id = incoming.id AND BINARY generic_templates.name = BINARY '通用缺陷修复 SOP'
    AND SHA2(CAST(generic_templates.payload AS CHAR CHARACTER SET utf8mb4),256) = '39520adce5ef1cf9190cede5e7b4b6db5e912706aab56b96b1a2e70ea2a13a3d',
    incoming.payload, generic_templates.payload),
  name = IF(generic_templates.id = incoming.id AND BINARY generic_templates.name = BINARY '通用缺陷修复 SOP'
    AND generic_templates.payload = incoming.payload, incoming.name, generic_templates.name);
INSERT IGNORE INTO generic_templates (id,name,payload,updated_at) VALUES ('generic-product-delivery','Product proposal SOP','{"Workflow":{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-product-delivery","name":"Product proposal SOP","revision":1,"status":"published","description":"Analyze requirements, write a product proposal and complete independent acceptance. No repository or Git token is required.","sandboxProfileId":"generic-docker","generic":true,"owner":"LoopForge","tags":["public"],"nodes":[{"id":"clarify","name":"Clarify requirements","type":"agent","agentId":"generic-product-delivery-clarify","maxAttempts":2,"position":{"x":100,"y":150},"artifactOutputs":[{"name":"clarify","path":"requirement.md","mediaType":"text/markdown","required":true}]},{"id":"design","name":"Design the solution","type":"agent","agentId":"generic-product-delivery-design","maxAttempts":2,"position":{"x":345,"y":150},"artifactOutputs":[{"name":"design","path":"design.md","mediaType":"text/markdown","required":true}]},{"id":"review","name":"Independent review","type":"agent","agentId":"generic-product-delivery-review","maxAttempts":2,"position":{"x":590,"y":150},"artifactOutputs":[{"name":"review","path":"review.md","mediaType":"text/markdown","required":true}]},{"id":"accept","name":"Human acceptance","type":"approval","maxAttempts":1,"rejectTo":"design","position":{"x":835,"y":150}},{"id":"deliver","name":"Delivery summary","type":"agent","agentId":"generic-product-delivery-deliver","maxAttempts":2,"position":{"x":1080,"y":150},"artifactOutputs":[{"name":"deliver","path":"delivery.md","mediaType":"text/markdown","required":true}]}],"edges":[{"id":"e-0","source":"clarify","target":"design","when":"success"},{"id":"e-1","source":"design","target":"review","when":"success"},{"id":"e-2","source":"review","target":"accept","when":"success"},{"id":"e-3","source":"accept","target":"deliver","when":"success"}]},"Agents":[{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-product-delivery-clarify","name":"Clarify requirements","executorId":"codebuddy","rules":["public-product-documents"],"skills":[],"mcpServers":[],"prompt":"Confirm the goals, scope, user scenarios, business boundaries and verifiable acceptance criteria in requirement.md. List assumptions and open questions.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-product-delivery-design","name":"Design the solution","executorId":"codebuddy","rules":["public-product-documents"],"skills":[],"mcpServers":[],"prompt":"Read requirement.md and document user journeys, feature scope, interactions, business rules, risks and acceptance criteria in design.md. Deliver documents only. This step requires no repository, coding or Git operations.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-product-delivery-review","name":"Independent review","executorId":"codebuddy","rules":["public-product-documents"],"skills":[],"mcpServers":[],"prompt":"Independently review design.md against requirement.md for completeness, consistency, edge cases and acceptance criteria. Record specific issues, locations, impact and changes in review.md. Write REJECT for blockers and never invent verification results.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"},{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"generic-product-delivery-deliver","name":"Delivery summary","executorId":"codebuddy","rules":["public-product-documents"],"skills":[],"mcpServers":[],"prompt":"After human acceptance, reconcile requirement.md, design.md and review.md. Record the delivered work, acceptance result, open questions, known limitations and deliverables in delivery.md. Deliver workspace documents only. No Git token, commits or PRs are required.\\n\\nComplete this step and deliver its artifacts in English.\\n\\n### Inputs\\n\\n- Requirement: {{input}}\\n- Repository context: {{repository}}"}],"Rules":[{"id":"public-product-documents","name":"Product documentation and acceptance rules","shared":true,"priority":100,"content":"Use the user’s input and workspace documents to write the product proposal. No repository, Git token or code build is required. Identify assumptions and open questions, protect credentials, and report only verified facts and acceptance results. Write and archive the required artifacts in the workspace. Explain blockers and request rework."}],"Skills":[]}',UTC_TIMESTAMP()) AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(generic_templates.id = incoming.id AND BINARY generic_templates.name = BINARY '通用产品方案 SOP'
    AND SHA2(CAST(generic_templates.payload AS CHAR CHARACTER SET utf8mb4),256) = 'bd24771d818b56f8b2b1a37de0b8e9faa432c1a8253ceb545981f75464ea4895',
    incoming.payload, generic_templates.payload),
  name = IF(generic_templates.id = incoming.id AND BINARY generic_templates.name = BINARY '通用产品方案 SOP'
    AND generic_templates.payload = incoming.payload, incoming.name, generic_templates.name);
INSERT IGNORE INTO workflows (`id`,`name`,`payload`,`version`,`revision`,`status`) VALUES ('welcome-workflow','Platform check · script & approval','{"version":1,"updatedAt":"2026-10-15T00:00:00Z","id":"welcome-workflow","name":"Platform check · script & approval","revision":1,"status":"published","projectId":"welcome","description":"Run a real script, inspect its artifact, then approve the run to resume it. No model key is needed.","sandboxProfileId":"local","nodes":[{"id":"prepare","name":"Generate acceptance report","type":"script","scriptLanguage":"shell","executionScope":"run","script":"mkdir -p reports\\nprintf ''# LoopForge local acceptance\\\\n\\\\nChecks: script execution, persistent artifacts, human approval and resumption.\\\\n'' > reports/welcome.md","maxAttempts":1,"position":{"x":100,"y":150},"artifactOutputs":[{"name":"welcome","path":"reports/welcome.md","mediaType":"text/markdown","required":true}]},{"id":"approve","name":"Review the acceptance report","type":"approval","maxAttempts":1,"rejectTo":"prepare","position":{"x":370,"y":150}},{"id":"finish","name":"Complete acceptance","type":"script","scriptLanguage":"shell","executionScope":"run","script":"printf ''# Acceptance complete\\\\n\\\\nApproval received. Execution resumed successfully.\\\\n'' > completed.md","artifactOutputs":[{"name":"completed","path":"completed.md","mediaType":"text/markdown","required":true}],"maxAttempts":1,"position":{"x":640,"y":150}}],"edges":[{"id":"e-1","source":"prepare","target":"approve","when":"success"},{"id":"e-2","source":"approve","target":"finish","when":"success"}]}',1,1,'published') AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(workflows.id = incoming.id AND BINARY workflows.name = BINARY '平台验收 · 脚本与审批'
    AND SHA2(CAST(workflows.payload AS CHAR CHARACTER SET utf8mb4),256) = '32039d1b211511d831afd52355b50da26e68bffb2320d79ca5e1704d5ae3e5a3',
    incoming.payload, workflows.payload),
  name = IF(workflows.id = incoming.id AND BINARY workflows.name = BINARY '平台验收 · 脚本与审批'
    AND workflows.payload = incoming.payload, incoming.name, workflows.name);
INSERT IGNORE INTO agents (id,name,payload,updated_at) VALUES ('baseline-align-resolver','Baseline alignment role','{"id":"baseline-align-resolver","name":"Baseline alignment role","version":1,"shared":true,"executorId":"codebuddy","rules":["public-engineering"],"skills":[],"mcpServers":[],"prompt":"Fetch the default branch and merge it into the current working branch. Resolve conflicts while preserving valid changes on both sides. Document uncertain choices. Create a local merge commit. Do not push, modify the default branch, run unrelated tests or write a fix report."}',UTC_TIMESTAMP()) AS incoming
ON DUPLICATE KEY UPDATE
  payload = IF(agents.id = incoming.id AND BINARY agents.name = BINARY '基线对齐执行员'
    AND SHA2(CAST(agents.payload AS CHAR CHARACTER SET utf8mb4),256) = 'bcbad0ec162700245f74258e52124cc3f103f050ac959ead186066a4d098e988',
    incoming.payload, agents.payload),
  name = IF(agents.id = incoming.id AND BINARY agents.name = BINARY '基线对齐执行员'
    AND agents.payload = incoming.payload, incoming.name, agents.name);
COMMIT;
